#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> scores{8, 3, 5};
    std::sort(scores.begin(), scores.end());
    for (int score : scores) {
        std::cout << score << "\n";
    }
}

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> scores{3, 8, 9};
    auto count = std::count_if(scores.begin(), scores.end(), [](int n) { return n > 5; });
    std::cout << count << "\n";
}

#include <iostream>

int main() {
    int limit = 7;
    auto passed = [limit](int score) { return score >= limit; };
    std::cout << std::boolalpha << passed(8) << "\n";
}
